CREATE TABLE IF NOT EXISTS monitor_state (id INTEGER PRIMARY KEY CHECK(id=1), payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monitor_samples (at INTEGER PRIMARY KEY, ok INTEGER NOT NULL, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS incidents (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, kind TEXT NOT NULL, at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS incidents_at ON incidents(at DESC);
CREATE TABLE IF NOT EXISTS vitals (day TEXT NOT NULL, release TEXT NOT NULL, name TEXT NOT NULL, bucket REAL NOT NULL, samples INTEGER NOT NULL, total REAL NOT NULL, PRIMARY KEY(day,release,name,bucket));
CREATE TABLE IF NOT EXISTS alert_outbox (id INTEGER PRIMARY KEY AUTOINCREMENT, payload TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS monitor_lock (id INTEGER PRIMARY KEY CHECK(id=1), owner TEXT NOT NULL, until INTEGER NOT NULL);
